PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('patient','caregiver')),created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS links(patient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,caregiver TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(patient,caregiver));
CREATE TABLE IF NOT EXISTS invites(hash TEXT PRIMARY KEY,patient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT NOT NULL,patient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,payload TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(id,patient));
CREATE TABLE IF NOT EXISTS receipts(patient TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,event_id TEXT NOT NULL,PRIMARY KEY(patient,event_id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT,at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS push_tokens(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS deliveries(record_id TEXT NOT NULL,patient TEXT NOT NULL,due INTEGER NOT NULL,PRIMARY KEY(record_id,patient,due));
